private val Bg = Color(0xFF080D16); private val Panel = Color(0xFF111925); private val Raised = Color(0xFF182434)
private val Mint = Color(0xFF70E1C1); private val Muted = Color(0xFF8795A9); private val Line = Color(0xFF243144)
private data class Media(val id:String=UUID.randomUUID().toString(),val name:String,val kind:String,val duration:Float=8f,val uri:String="",val color:Color=Color(0xFF37B6A0),val effects:List<String> = emptyList())
private data class Track(val id:String,val name:String,val tint:Color,val audio:Boolean=false)

class EditorViewModel: ViewModel() {
    var media by mutableStateOf(listOf(Media(name="Coastal drive.mp4",kind="VIDEO",duration=12f,color=Color(0xFF347DA2)),Media(name="Golden hour.mp4",kind="VIDEO",duration=9f,color=Color(0xFFE08B62)),Media(name="Forest path.mp4",kind="VIDEO",duration=16f,color=Color(0xFF517C61)),Media(name="ambient-score.wav",kind="AUDIO",duration=31f,color=Color(0xFF9877DB)),Media(name="cover-frame.jpg",kind="IMAGE",duration=5f,color=Color(0xFFCDAB72))))
    var tracks by mutableStateOf(listOf(Track("v1","VIDEO 01",Color(0xFF46CDB0)),Track("v2","OVERLAY",Color(0xFFB17AE5)),Track("a1","AUDIO 01",Color(0xFFFFB765),true)))
    var selected by mutableStateOf<String?>(null); var playing by mutableStateOf(false); var playhead by mutableFloatStateOf(8.4f)
    var search by mutableStateOf(""); var folder by mutableStateOf("All media"); var notice by mutableStateOf(""); var copied by mutableStateOf<Media?>(null)
    var scale by mutableFloatStateOf(1f); val undoStack= mutableListOf<List<Media>>()
    fun add(uri:Uri,name:String){media=media+Media(name=name,kind=if(name.endsWith(".wav")||name.endsWith(".mp3"))"AUDIO" else if(name.endsWith(".jpg")||name.endsWith(".png"))"IMAGE" else "VIDEO",uri=uri.toString(),color=Color(0xFF438B97));notice="Imported $name"}
    fun selectedClip()=media.firstOrNull{it.id==selected}
    fun duplicate(){val m=selectedClip()?:return;media=media+ m.copy(id=UUID.randomUUID().toString(),name=m.name.substringBeforeLast('.')+" copy."+m.name.substringAfterLast('.'));notice="Clip duplicated"}
    fun copy(){copied=selectedClip();notice=if(copied!=null)"Copied to clipboard" else "Select a clip first"}
    fun paste(){copied?.let{media=media+it.copy(id=UUID.randomUUID().toString(),name=it.name.substringBeforeLast('.')+" copy."+it.name.substringAfterLast('.'));notice="Pasted clip"}}
    fun delete(){if(selected!=null){media=media.filterNot{it.id==selected};selected=null;notice="Clip removed"}}
    fun split(){val m=selectedClip()?:return;undoStack.add(media);val first=m.copy(duration=(m.duration/2).coerceAtLeast(1f));val second=m.copy(id=UUID.randomUUID().toString(),name=m.name.substringBeforeLast('.')+" — part 2."+m.name.substringAfterLast('.'),duration=(m.duration/2).coerceAtLeast(1f));media=media.flatMap{if(it.id==m.id)listOf(first,second)else listOf(it)};selected=second.id;notice="Split at ${"%.1f".format(playhead)}s"}
    fun effect(name:String){val id=selected?:return;media=media.map{if(it.id==id)it.copy(effects=if(name in it.effects)it.effects-name else it.effects+name)else it};notice="$name applied to selected clip"}
}

class MainActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);window.statusBarColor=android.graphics.Color.rgb(8,13,22);window.navigationBarColor=android.graphics.Color.rgb(8,13,22);setContent { MaterialTheme(colorScheme=darkColorScheme(primary=Mint,background=Bg,surface=Panel)){EditorScreen() } }}}

@Composable private fun EditorScreen(vm:EditorViewModel= viewModel()){
    var tab by remember{mutableStateOf("Media")}; var export by remember{mutableStateOf(false)}
    val context=androidx.compose.ui.platform.LocalContext.current
    val picker= rememberLauncherForActivityResult(ActivityResultContracts.OpenMultipleDocuments()){uris->uris.forEach{uri->try{val column=android.provider.OpenableColumns.DISPLAY_NAME;val cursor=context.contentResolver.query(uri,null,null,null,null);val name=cursor?.use{if(it.moveToFirst())it.getString(it.getColumnIndexOrThrow(column))else "Imported media"}?:"Imported media";vm.add(uri,name)}catch(_:Exception){vm.add(uri,"Imported media")}}}
    Column(Modifier.fillMaxSize().background(Bg)) {
        Header(onExport={export=true},onUndo={vm.notice="Undo: latest edit reverted"},onRedo={vm.notice="Nothing to redo"})
        Row(Modifier.weight(1f).fillMaxWidth()) {
            Library(vm,tab,{tab=it},{picker.launch(arrayOf("video/*","image/*","audio/*"))})
            Column(Modifier.weight(1f).fillMaxHeight().padding(horizontal=14.dp, vertical=10.dp),verticalArrangement=Arrangement.spacedBy(10.dp)) {
                Preview(vm)
                Timeline(vm)
            }
            Inspector(vm)
        }
    }
    if(vm.notice.isNotEmpty()) LaunchedEffect(vm.notice){ kotlinx.coroutines.delay(2200);vm.notice="" }
    if(vm.notice.isNotEmpty()) Box(Modifier.fillMaxSize().padding(bottom=65.dp),contentAlignment=Alignment.BottomCenter){Surface(color=Raised,shape=RoundedCornerShape(12.dp)){Text(vm.notice,Modifier.padding(horizontal=18.dp,vertical=11.dp),color=Mint,fontSize=12.sp)}}
    if(export) AlertDialog(onDismissRequest={export=false},containerColor=Panel,title={Text("Export master",color=Color.White)},text={Column{Text("High quality · H.265 / HEVC",color=Muted);Spacer(Modifier.height(12.dp));Text("Resolution",color=Color.White);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){listOf("1080p","4K UHD").forEach{Surface(color=Raised,shape=RoundedCornerShape(8.dp)){Text(it,Modifier.clickable{vm.notice="$it export queued";export=false}.padding(12.dp),color=Mint)}}};Spacer(Modifier.height(10.dp));Text("4K export requires a compatible device and available storage.",color=Muted,fontSize=11.sp)}},confirmButton={TextButton(onClick={vm.notice="Export queued";export=false}){Text("Export",color=Mint)}},dismissButton={TextButton(onClick={export=false}){Text("Cancel",color=Muted)}})
}

@Composable private fun Header(onExport:()->Unit,onUndo:()->Unit,onRedo:()->Unit){Row(Modifier.fillMaxWidth().height(54.dp).background(Panel).padding(horizontal=16.dp),verticalAlignment=Alignment.CenterVertically){Text("◈",color=Mint,fontSize=25.sp,fontWeight=FontWeight.Bold);Spacer(Modifier.width(9.dp));Column{Text("OPENCLIPFLOW",color=Color.White,fontSize=13.sp,fontWeight=FontWeight.Bold,letterSpacing=1.5.sp);Text("STUDIO  /  Untitled project",color=Muted,fontSize=9.sp)};Spacer(Modifier.width(28.dp));Text("☁  Local project",color=Muted,fontSize=10.sp);Spacer(Modifier.weight(1f));IconButton(onClick=onUndo){Icon(Icons.Default.Undo,"Undo",tint=Muted)};IconButton(onClick=onRedo){Icon(Icons.Default.Redo,"Redo",tint=Muted)};Spacer(Modifier.width(9.dp));Surface(color=Raised,shape=RoundedCornerShape(7.dp)){Text("  UHD 4K  ·  30 FPS  ",Modifier.padding(vertical=8.dp),color=Mint,fontSize=10.sp)};Spacer(Modifier.width(12.dp));Button(onClick=onExport,colors=ButtonDefaults.buttonColors(containerColor=Mint,contentColor=Bg),shape=RoundedCornerShape(7.dp),contentPadding=PaddingValues(horizontal=18.dp, vertical=8.dp)){Text("Export",fontWeight=FontWeight.Bold,fontSize=12.sp)}}}

@Composable private fun Library(vm:EditorViewModel,tab:String,onTab:(String)->Unit,onImport:()->Unit){Column(Modifier.width(224.dp).fillMaxHeight().background(Panel).padding(12.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text("PROJECT",color=Muted,fontSize=10.sp,fontWeight=FontWeight.Bold,letterSpacing=1.sp);Spacer(Modifier.weight(1f));IconButton(onClick=onImport,modifier=Modifier.size(30.dp)){Icon(Icons.Default.Add,"Import",tint=Mint,modifier=Modifier.size(18.dp))}};Spacer(Modifier.height(7.dp));listOf("All media","Favorites","Recent","NAS · Studio archive").forEachIndexed{i,s->Row(Modifier.fillMaxWidth().clickable{vm.folder=s}.background(if(vm.folder==s)Raised else Color.Transparent,RoundedCornerShape(6.dp)).padding(8.dp),verticalAlignment=Alignment.CenterVertically){Text(listOf("▦","☆","◷","⌘")[i],color=if(vm.folder==s)Mint else Muted,fontSize=14.sp);Spacer(Modifier.width(8.dp));Text(s,color=if(vm.folder==s)Color.White else Muted,fontSize=11.sp);if(i==3)Text("  SMB",color=Mint,fontSize=8.sp)}};Spacer(Modifier.height(14.dp));HorizontalDivider(color=Line);Spacer(Modifier.height(9.dp));Row{listOf("Media","Folders").forEach{Text(it,Modifier.clickable{onTab(it)}.padding(end=17.dp,bottom=8.dp),color=if(tab==it)Mint else Muted,fontSize=11.sp,fontWeight=FontWeight.SemiBold)}};OutlinedTextField(value=vm.search,onValueChange={vm.search=it},modifier=Modifier.fillMaxWidth().height(46.dp),placeholder={Text("Search assets…",fontSize=10.sp)},singleLine=true,shape=RoundedCornerShape(8.dp),colors=OutlinedTextFieldDefaults.colors(focusedBorderColor=Mint,unfocusedBorderColor=Line,focusedTextColor=Color.White,unfocusedTextColor=Color.White,unfocusedContainerColor=Bg,focusedContainerColor=Bg));Spacer(Modifier.height(8.dp));if(tab=="Media")LazyColumn(verticalArrangement=Arrangement.spacedBy(5.dp),modifier=Modifier.weight(1f)){items(vm.media.filter{it.name.contains(vm.search,true)}){m->MediaRow(m,vm.selected==m.id){vm.selected=m.id}}}else LazyColumn(Modifier.weight(1f)){items(listOf("📁  Footage","   📁  Day one","   📁  Day two","📁  Audio","📁  Exports")){Text(it,Modifier.fillMaxWidth().clickable{vm.notice="Folder selected"}.padding(vertical=8.dp),color=Muted,fontSize=11.sp)}};HorizontalDivider(color=Line);Text("IMPORT MEDIA",Modifier.fillMaxWidth().clickable(onClick=onImport).padding(vertical=12.dp),color=Mint,fontSize=10.sp,fontWeight=FontWeight.Bold)} }

@Composable private fun MediaRow(m:Media,selected:Boolean,onClick:()->Unit){Row(Modifier.fillMaxWidth().clickable(onClick=onClick).background(if(selected)Raised else Color.Transparent,RoundedCornerShape(7.dp)).padding(5.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(52.dp,36.dp).background(Brush.linearGradient(listOf(m.color,m.color.copy(alpha=.35f))),RoundedCornerShape(5.dp)),contentAlignment=Alignment.Center){Text(if(m.kind=="AUDIO")"♫" else "▶",color=Color.White,fontSize=12.sp)};Spacer(Modifier.width(8.dp));Column(Modifier.weight(1f)){Text(m.name,color=if(selected)Color.White else Color(0xFFC3CEDA),fontSize=9.sp,maxLines=1);Text("${m.kind} · ${"%.1f".format(m.duration)}s",color=Muted,fontSize=8.sp)}}}

@Composable private fun Preview(vm:EditorViewModel){Column(Modifier.weight(1f).fillMaxWidth().background(Color(0xFF060A10),RoundedCornerShape(11.dp)).border(1.dp,Line,RoundedCornerShape(11.dp)).padding(10.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text("PREVIEW",color=Muted,fontSize=9.sp,fontWeight=FontWeight.Bold,letterSpacing=1.sp);Spacer(Modifier.weight(1f));Text("FIT  ·  3840 × 2160",color=Muted,fontSize=9.sp)};Box(Modifier.weight(1f).fillMaxWidth(),contentAlignment=Alignment.Center){Box(Modifier.fillMaxHeight(.82f).aspectRatio(16f/9f).background(Brush.linearGradient(listOf(Color(0xFF263B46),Color(0xFF9C7257),Color(0xFF172C36))),RoundedCornerShape(5.dp)),contentAlignment=Alignment.Center){Text("OPENCLIPFLOW   /   PREVIEW",color=Color.White.copy(alpha=.78f),fontSize=10.sp,fontWeight=FontWeight.SemiBold);Text("4K",Modifier.align(Alignment.BottomEnd).padding(10.dp),color=Color.White.copy(alpha=.7f),fontSize=9.sp)}};Row(verticalAlignment=Alignment.CenterVertically){IconButton(onClick={vm.playhead=(vm.playhead-1f).coerceAtLeast(0f)}){Icon(Icons.Default.SkipPrevious,"Previous frame",tint=Muted)};IconButton(onClick={vm.playing=!vm.playing}){Icon(if(vm.playing)Icons.Default.Pause else Icons.Default.PlayArrow,"Play / pause",tint=Mint)};IconButton(onClick={vm.playhead+=1f}){Icon(Icons.Default.SkipNext,"Next frame",tint=Muted)};Spacer(Modifier.weight(1f));Text("00:${"%02d".format(vm.playhead.toInt())}:${"%02d".format(((vm.playhead%1)*30).toInt())}   /   00:42:18",color=Color.White,fontSize=10.sp,fontWeight=FontWeight.Medium)}}}

@Composable private fun Timeline(vm:EditorViewModel){Column(Modifier.fillMaxWidth().height(252.dp).background(Panel,RoundedCornerShape(10.dp)).padding(10.dp)){Row(verticalAlignment=Alignment.CenterVertically){Text("TIMELINE",color=Color.White,fontSize=10.sp,fontWeight=FontWeight.Bold,letterSpacing=1.sp);Spacer(Modifier.width(8.dp));Text("30 FPS",color=Muted,fontSize=9.sp);Spacer(Modifier.weight(1f));IconButton(onClick={vm.scale=(vm.scale*.8f).coerceAtLeast(.55f)},modifier=Modifier.size(28.dp)){Icon(Icons.Default.Remove,"Zoom out",tint=Muted)};Text("${(100*vm.scale).toInt()}%",color=Muted,fontSize=9.sp);IconButton(onClick={vm.scale=(vm.scale*1.25f).coerceAtMost(2.5f)},modifier=Modifier.size(28.dp)){Icon(Icons.Default.Add,"Zoom in",tint=Muted)};SmallAction("✂","Split"){vm.split()};SmallAction("⧉","Copy"){vm.copy()};SmallAction("▣","Paste"){vm.paste()};SmallAction("＋","Add track"){vm.tracks=vm.tracks+Track(UUID.randomUUID().toString(),"VIDEO 0${vm.tracks.size+1}",Color(0xFF9877DB));vm.notice="Track added"}}
    Row(Modifier.fillMaxWidth().height(22.dp)){Spacer(Modifier.width(76.dp));for(i in 0..8)Text("${i*5}s",Modifier.weight(1f),color=Muted,fontSize=8.sp)}
    vm.tracks.forEachIndexed{index,t->Row(Modifier.fillMaxWidth().height(48.dp).padding(bottom=4.dp)){Column(Modifier.width(76.dp).fillMaxHeight().background(Raised,RoundedCornerShape(5.dp)).padding(start=7.dp),verticalArrangement=Arrangement.Center){Text(t.name,color=t.tint,fontSize=8.sp,fontWeight=FontWeight.Bold);Text(if(t.audio)"♫  stereo" else "◉  video",color=Muted,fontSize=8.sp)};Box(Modifier.weight(1f).fillMaxHeight().background(Bg,RoundedCornerShape(5.dp)).pointerInput(t.id){var dx=0f;detectDragGestures(onDrag={change,drag->change.consume();dx+=drag.x;if(kotlin.math.abs(dx)>38){vm.playhead=(vm.playhead+if(dx>0)1f else -1f).coerceAtLeast(0f);dx=0f}},onDragEnd={})}){Row(Modifier.fillMaxHeight().padding(start=if(index==0)4.dp else 40.dp),horizontalArrangement=Arrangement.spacedBy(4.dp)){vm.media.filter{if(t.audio)it.kind=="AUDIO" else it.kind!="AUDIO"}.take(if(index==0)3 else 2).forEachIndexed{n,m->val width=(m.duration*8*vm.scale).coerceIn(65f,190f);Row(Modifier.width(width.dp).fillMaxHeight().padding(vertical=3.dp).background(Brush.verticalGradient(listOf(m.color.copy(alpha=.92f),m.color.copy(alpha=.62f))),RoundedCornerShape(5.dp)).border(if(vm.selected==m.id)1.5.dp else 0.dp,if(vm.selected==m.id)Mint else Color.Transparent,RoundedCornerShape(5.dp)).clickable{vm.selected=m.id},verticalAlignment=Alignment.CenterVertically){Text(if(t.audio)"  〰" else "  ▣",color=Color.White,fontSize=9.sp);Text(m.name,Modifier.weight(1f).padding(horizontal=3.dp),color=Color.White,fontSize=8.sp,maxLines=1);if(vm.selected==m.id)Text("◇ ",color=Color.White,fontSize=8.sp)}}}};Box(Modifier.offset(x=(76f+vm.playhead*8*vm.scale).dp).fillMaxHeight().width(1.dp).background(Color(0xFFFF6E83)))}}
    Row(horizontalArrangement=Arrangement.spacedBy(7.dp)){SmallAction("⧉","Duplicate"){vm.duplicate()};SmallAction("⌫","Delete"){vm.delete()};SmallAction("✦","Apply look"){vm.effect("Cinematic")};Text("Drag clips · Select a clip · Split at playhead",Modifier.padding(start=8.dp,top=7.dp),color=Muted,fontSize=8.sp)}
} }
