@Composable private fun Inspector(vm:EditorViewModel){Column(Modifier.width(206.dp).fillMaxHeight().background(Panel).padding(12.dp)){Text("INSPECTOR",color=Muted,fontSize=10.sp,fontWeight=FontWeight.Bold,letterSpacing=1.sp);Spacer(Modifier.height(12.dp));val m=vm.selectedClip();if(m==null){Text("Nothing selected",color=Color.White,fontSize=13.sp,fontWeight=FontWeight.SemiBold);Spacer(Modifier.height(5.dp));Text("Select a clip to inspect properties, metadata and effects.",color=Muted,fontSize=10.sp);Spacer(Modifier.height(16.dp));HorizontalDivider(color=Line);Spacer(Modifier.height(12.dp));Text("QUICK TOOLS",color=Muted,fontSize=9.sp,fontWeight=FontWeight.Bold);listOf("Color grading","Stabilization","Audio cleanup","AI scene detection").forEach{Text("✦  $it",Modifier.fillMaxWidth().clickable{vm.notice="$it selected"}.padding(vertical=11.dp),color=Color(0xFFD0DAE5),fontSize=10.sp)}}else{Text(m.name,color=Color.White,fontSize=12.sp,fontWeight=FontWeight.SemiBold);Text("${m.kind}  ·  ${"%.2f".format(m.duration)}s",color=Muted,fontSize=9.sp);Spacer(Modifier.height(12.dp));HorizontalDivider(color=Line);InspectorSection("TRANSFORM");Property("Position X","0 px");Property("Position Y","0 px");Property("Scale","100%");Property("Rotation","0°");Spacer(Modifier.height(9.dp));HorizontalDivider(color=Line);InspectorSection("COLOR · EFFECTS");listOf("Cinematic","Warm film","Soft glow","Vignette").forEach{e->Row(Modifier.fillMaxWidth().clickable{vm.effect(e)}.padding(vertical=5.dp),verticalAlignment=Alignment.CenterVertically){Checkbox(e in m.effects,onCheckedChange={vm.effect(e)},modifier=Modifier.size(22.dp),colors=CheckboxDefaults.colors(checkedColor=Mint,uncheckedColor=Muted));Text(e,color=Color(0xFFD0DAE5),fontSize=9.sp)}};Spacer(Modifier.height(8.dp));HorizontalDivider(color=Line);InspectorSection("METADATA · EXIF");Property("Duration","${"%.1f".format(m.duration)} sec");Property("Resolution","3840 × 2160");Property("Frame rate","30 fps");Property("Codec","HEVC / H.265");if(m.uri.isNotBlank())Property("Source","Imported media");Spacer(Modifier.height(8.dp));OutlinedButton(onClick={vm.notice="Applied effects to selected clip"},modifier=Modifier.fillMaxWidth(),colors=ButtonDefaults.outlinedButtonColors(contentColor=Mint),border=BorderStroke(1.dp,Line)){Text("Apply to selection",fontSize=9.sp)}}} }
